-- Create "problems" table
CREATE TABLE "problems" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "slug" character varying NOT NULL, "title" character varying NOT NULL, "difficulty" character varying NOT NULL, "statement_md" text NOT NULL, "time_limit_ms" bigint NOT NULL, "memory_limit_mb" bigint NOT NULL, "checker" character varying NOT NULL DEFAULT 'exact', "version" bigint NOT NULL DEFAULT 1, "published" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "problems_slug_key" to table: "problems"
CREATE UNIQUE INDEX "problems_slug_key" ON "problems" ("slug");
-- Create "tags" table
CREATE TABLE "tags" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying NOT NULL, PRIMARY KEY ("id"));
-- Create index "tags_name_key" to table: "tags"
CREATE UNIQUE INDEX "tags_name_key" ON "tags" ("name");
-- Create "problem_tags" table
CREATE TABLE "problem_tags" ("problem_id" bigint NOT NULL, "tag_id" bigint NOT NULL, PRIMARY KEY ("problem_id", "tag_id"), CONSTRAINT "problem_tags_problem_id" FOREIGN KEY ("problem_id") REFERENCES "problems" ("id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "problem_tags_tag_id" FOREIGN KEY ("tag_id") REFERENCES "tags" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create "users" table
CREATE TABLE "users" ("id" character varying NOT NULL, "username" character varying NOT NULL, "role" character varying NOT NULL DEFAULT 'user', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "users_username_key" to table: "users"
CREATE UNIQUE INDEX "users_username_key" ON "users" ("username");
-- Create "submissions" table
CREATE TABLE "submissions" ("id" uuid NOT NULL, "problem_version" bigint NOT NULL, "language" character varying NOT NULL, "source" character varying NOT NULL, "idempotency_key" character varying NOT NULL, "request_hash" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'queued', "verdict" character varying NULL, "runtime_ms" bigint NULL, "memory_kb" bigint NULL, "compile_output" text NULL, "attempt" bigint NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "judged_at" timestamptz NULL, "problem_id" bigint NOT NULL, "user_id" character varying NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "submissions_problems_submissions" FOREIGN KEY ("problem_id") REFERENCES "problems" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "submissions_users_submissions" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "submission_status_updated_at" to table: "submissions"
CREATE INDEX "submission_status_updated_at" ON "submissions" ("status", "updated_at");
-- Create index "submission_user_id_created_at" to table: "submissions"
CREATE INDEX "submission_user_id_created_at" ON "submissions" ("user_id", "created_at");
-- Create index "submission_user_id_idempotency_key" to table: "submissions"
CREATE UNIQUE INDEX "submission_user_id_idempotency_key" ON "submissions" ("user_id", "idempotency_key");
-- Create "submission_results" table
CREATE TABLE "submission_results" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "ordinal" bigint NOT NULL, "verdict" character varying NOT NULL, "runtime_ms" bigint NOT NULL DEFAULT 0, "memory_kb" bigint NOT NULL DEFAULT 0, "submission_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "submission_results_submissions_results" FOREIGN KEY ("submission_id") REFERENCES "submissions" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "submissionresult_submission_id_ordinal" to table: "submission_results"
CREATE UNIQUE INDEX "submissionresult_submission_id_ordinal" ON "submission_results" ("submission_id", "ordinal");
-- Create "test_cases" table
CREATE TABLE "test_cases" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "problem_version" bigint NOT NULL, "ordinal" bigint NOT NULL, "input" text NOT NULL, "expected_output" text NOT NULL, "is_sample" boolean NOT NULL DEFAULT false, "problem_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "test_cases_problems_test_cases" FOREIGN KEY ("problem_id") REFERENCES "problems" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "testcase_problem_id_problem_version_ordinal" to table: "test_cases"
CREATE UNIQUE INDEX "testcase_problem_id_problem_version_ordinal" ON "test_cases" ("problem_id", "problem_version", "ordinal");
